import type { CardCheck } from '@/lib/flashcard-check-core'

/**
 * Card-check questions for the cards of `mcat-cell-biology-cell-cycle-mcat`: one per card, keyed by the
 * card's exact front text. Each asks the student to use the card's idea in a
 * new situation. Gate: scripts/flashcard-checks/validate.ts.
 */
const r = String.raw

export const checks: Record<string, CardCheck> = {
  [r`What happens at the G₁/S (restriction) checkpoint?`]: {
    question: r`Cultured fibroblasts are growing in serum. The serum growth factors are then washed away. What happens to a cell that had already begun copying its DNA when the serum was removed?`,
    options: [r`It stops at once, with its DNA only partly copied`, r`It finishes S phase, then stops in G₂ before mitosis`, r`It finishes S, G₂ and M, then stops in the next G₁`, r`It finishes S and G₂, then stops at metaphase of M`],
    correctAnswer: 2,
    explanation: r`The G₁/S restriction checkpoint is the point of no return: growth signals are checked there, and a cell past it completes the cycle without them. Its daughters then stop at the next G₁, where the signals are checked again. Stopping mid-S, in G₂ or at metaphase would need a growth-factor check at those points, and none exists.`,
  },
  [r`What do cell cycle checkpoints verify?`]: {
    question: r`A cell in G₁ is small and poorly fed, but its DNA is intact. Which checkpoint holds this cell, and what step does the hold prevent?`,
    options: [r`The G₁/S checkpoint, which prevents the start of DNA replication`, r`The G₂/M checkpoint, which prevents the start of DNA replication`, r`The G₂/M checkpoint, which prevents the start of chromosome condensation`, r`The spindle checkpoint, which prevents the start of chromatid separation`],
    correctAnswer: 0,
    explanation: r`Cell size is verified at G₁/S, before the cell commits to copying its DNA. The G₂/M checkpoint asks whether replication is complete and guards entry into mitosis, not replication. The spindle checkpoint asks only whether every chromosome is attached to the spindle.`,
  },
  [r`How does meiosis differ from mitosis?`]: {
    question: r`An insect has a diploid number of 12. One of its cells divides by mitosis and another completes meiosis. What are the products?`,
    options: [r`Mitosis: 2 cells with 12 chromosomes; meiosis: 4 cells with 6`, r`Mitosis: 2 cells with 6 chromosomes; meiosis: 4 cells with 12`, r`Mitosis: 4 cells with 12 chromosomes; meiosis: 2 cells with 6`, r`Mitosis: 2 cells with 12 chromosomes; meiosis: 4 cells with 3`],
    correctAnswer: 0,
    explanation: r`Mitosis is one division that gives 2 identical diploid cells (12 each). Meiosis is two divisions that give 4 haploid cells, so each has 12/2 = 6. Swapping the chromosome numbers or the cell counts confuses the two processes, and 3 comes from wrongly halving the number at both meiotic divisions.`,
  },
  [r`When do crossing over and independent assortment occur?`]: {
    question: r`Genes A and B lie on the same chromosome. A parent carries A and B on one homolog and a and b on the other, yet some of its gametes carry A with b. Which event produced these gametes, and when did it occur?`,
    options: [r`Crossing over, during prophase II`, r`Crossing over, during prophase I`, r`Independent assortment, at metaphase I`, r`Independent assortment, at metaphase II`],
    correctAnswer: 1,
    explanation: r`New combinations of alleles on the SAME chromosome can only come from crossing over, which happens between paired homologs in prophase I. Independent assortment at metaphase I shuffles whole chromosomes, so it cannot separate A from B on one chromosome. Homologs are no longer paired in meiosis II, so neither event happens there.`,
  },
  [r`What separates in anaphase I vs. anaphase II?`]: {
    question: r`An animal has a diploid number of 8. During anaphase I of meiosis in one of its cells, what moves toward each pole?`,
    options: [r`8 chromosomes, each made of two sister chromatids`, r`4 chromosomes, each made of two sister chromatids`, r`4 chromosomes, each made of one single chromatid`, r`8 chromosomes, each made of one single chromatid`],
    correctAnswer: 1,
    explanation: r`Anaphase I separates homologous chromosomes, so each pole receives one member of each of the 4 pairs, and the sisters stay joined. Single chromatids moving apart describes anaphase II or mitosis, where sister chromatids separate. Eight per pole ignores that the homolog pairs are being split.`,
  },
  [r`How do cyclins and CDKs drive the cycle?`]: {
    question: r`Through the cell cycle the amount of CDK1 protein in a cell stays constant, yet its kinase activity is near zero in G₁ and peaks sharply at mitosis. What best explains this?`,
    options: [r`Its cyclin partner builds up and binds it only near mitosis`, r`Its cyclin partner removes phosphates from it near mitosis`, r`The CDK1 gene is transcribed and translated only at mitosis`, r`The CDK1 protein is destroyed and rebuilt in every G₁ phase`],
    correctAnswer: 0,
    explanation: r`A CDK is active only when bound to a cyclin, and it is the cyclin level that rises and falls through the cycle. Options that have the CDK itself made only at mitosis or destroyed every G₁ contradict its constant level. Cyclins are regulatory subunits, not phosphatases.`,
  },
  [r`What is nondisjunction?`]: {
    question: r`Because of a meiotic segregation failure, a sperm carries 22 chromosomes instead of 23. It fertilizes a normal egg. What does the zygote have?`,
    options: [r`47 chromosomes, a trisomy`, r`46 chromosomes, a euploid set`, r`45 chromosomes, a monosomy`, r`69 chromosomes, a triploidy`],
    correctAnswer: 2,
    explanation: r`Nondisjunction gives gametes with one chromosome too many or too few. Here 22 + 23 = 45, so the zygote is missing one chromosome (monosomy). A trisomy (47) would need the gamete with the extra copy, 24 + 23. Triploidy is a whole extra set, which nondisjunction of one chromosome does not produce.`,
  },
  [r`List the phases of the cell cycle.`]: {
    question: r`A cell has an intact nuclear envelope and uncondensed chromatin. Its DNA content is exactly twice that of a newly divided cell and is no longer rising. Which phase is it in?`,
    options: [r`G₂ of interphase`, r`G₁ of interphase`, r`S of interphase`, r`Prophase of M`],
    correctAnswer: 0,
    explanation: r`Doubled DNA that is no longer rising means replication (S) is complete, and an intact envelope with uncondensed chromatin means mitosis has not begun, so the cell is in G₂. A G₁ cell would still have the unreplicated amount, an S cell would still be rising, and prophase shows condensing chromosomes.`,
  },
  [r`What happens in each mitotic stage?`]: {
    question: r`In a fixed dividing cell, two equal groups of single-chromatid chromosomes are partway to opposite poles of the spindle, and no nuclear envelope is present. Which stage of mitosis is this?`,
    options: [r`Prophase`, r`Metaphase`, r`Anaphase`, r`Telophase`],
    correctAnswer: 2,
    explanation: r`Sister chromatids that have separated and are moving to opposite poles define anaphase. In prophase the chromosomes are only condensing, and in metaphase they sit together at the central plate with sisters still joined. Telophase begins once they have arrived and nuclear envelopes re-form.`,
  },
  [r`Maturation promoting factor (MPF) consists of:`]: {
    question: r`A researcher purifies the factor that drives cells into mitosis and finds two subunits. She then measures the amount of each through the cycle. What should she find?`,
    options: [r`Cyclin B, which stays constant, and CDK1, which rises and falls`, r`Cyclin B, which rises and falls, and CDK1, which stays constant`, r`Cyclin D, which rises and falls, and CDK4, which stays constant`, r`Cyclin E, which stays constant, and CDK2, which rises and falls`],
    correctAnswer: 1,
    explanation: r`MPF is cyclin B bound to CDK1, and as with every cyclin-CDK pair it is the cyclin whose level oscillates. Reversing which subunit oscillates gets the regulation backward. Cyclin D-CDK4 and cyclin E-CDK2 act in G₁ and at G₁/S, not at entry into mitosis.`,
  },
  [r`An oncogene differs from a tumor suppressor in that an oncogene is:`]: {
    question: r`In a tumor, a gene with a normal sequence is present in 30 copies, and the excess protein pushes cells through G₁. How is this gene classified, and what should a drug against it do?`,
    options: [r`An oncogene; the drug should inhibit its protein product`, r`An oncogene; the drug should restore its protein product`, r`A tumor suppressor; the drug should inhibit its protein product`, r`A tumor suppressor; the drug should restore its protein product`],
    correctAnswer: 0,
    explanation: r`A gene that promotes division and causes cancer through too much activity (gain of function) is an oncogene, so treatment aims to block its product. Restoring a missing product is the logic for a tumor suppressor, which causes cancer through loss of function. Here nothing is lost: the protein is in excess.`,
  },
  [r`Colchicine disrupts mitosis by:`]: {
    question: r`Before making a karyotype, a lab adds colchicine to dividing blood cells for a short time. Why does this help?`,
    options: [r`It blocks spindle assembly, so cells collect in metaphase with condensed chromosomes`, r`It locks spindles in place, so cells collect in metaphase with condensed chromosomes`, r`It blocks DNA synthesis, so cells collect in S phase with fully extended chromosomes`, r`It blocks the actin ring, so cells collect in telophase with two separate nuclei`],
    correctAnswer: 0,
    explanation: r`Colchicine prevents tubulin from polymerizing, so no spindle forms and cells stop in mitosis with condensed, countable chromosomes. Stabilizing microtubules that already exist is how Taxol works, the opposite mechanism. Colchicine does not act on DNA synthesis or on the actin ring of cytokinesis.`,
  },
  [r`DNA replication occurs during which phase?`]: {
    question: r`Over 8 hours, the DNA content of a human skin cell rises steadily from 6 pg to 12 pg. Which phase is this, and how many chromosomes does the cell have when it ends?`,
    options: [r`S phase; now 92 chromosomes`, r`S phase; still 46 chromosomes`, r`G₂ phase; still 46 chromosomes`, r`M phase; now 92 chromosomes`],
    correctAnswer: 1,
    explanation: r`DNA content doubles only during S phase, when each chromosome is replicated. Chromosomes are counted by centromeres, so each replicated chromosome (two sister chromatids) still counts as one and the number stays 46. In G₂ the DNA content is already doubled and constant, and in M phase it does not rise.`,
  },
  [r`A cell in $G_2$ has how many chromatids per chromosome?`]: {
    question: r`A fly has a diploid number of 10. How many chromosomes and how many chromatids does one of its cells contain during G₂?`,
    options: [r`10 chromosomes and 20 chromatids`, r`10 chromosomes and 10 chromatids`, r`20 chromosomes and 20 chromatids`, r`5 chromosomes and 10 chromatids`],
    correctAnswer: 0,
    explanation: r`By G₂ every chromosome has been replicated in S phase and consists of two sister chromatids joined at one centromere, so 10 chromosomes carry 20 chromatids. Ten chromatids describes G₁, before replication. Counting 20 chromosomes treats each chromatid as a chromosome, and 5 chromosomes is the haploid number.`,
  },
  [r`During $G_1$, the cell primarily:`]: {
    question: r`A newly formed daughter cell has half its mother's mass and too few ribosomes and mitochondria. In which phase does it mainly make up this shortfall, and what is that phase's chief activity?`,
    options: [r`G₂: final checks and the preparation for mitosis`, r`S: the copying of every chromosome's DNA strands`, r`M: condensing and then separating the chromosomes`, r`G₁: general growth and the synthesis of organelles`],
    correctAnswer: 3,
    explanation: r`G₁ follows division directly and is the main growth phase, when the cell makes proteins and organelles and reaches the size needed to commit to S phase. S phase is devoted to DNA replication, G₂ to preparing specifically for mitosis, and M to dividing the chromosomes.`,
  },
  [r`At anaphase onset, APC/C-Cdc20 ubiquitinates {{c1::securin}}, freeing separase.`]: {
    question: r`Cells are engineered so that securin can be destroyed on command. Securin is destroyed in a metaphase cell whose spindle checkpoint is still holding APC/C inactive. What is the most likely result?`,
    options: [r`Separase is released and sister chromatids separate too early`, r`Separase is destroyed and sister chromatids remain held together`, r`Cyclin B is released and the cell slips back into G₂ too early`, r`Cohesin is reinforced and sister chromatids remain held together`],
    correctAnswer: 0,
    explanation: r`Securin is the inhibitor that holds separase inactive, so removing it frees separase to open cohesin whether or not the checkpoint is satisfied. Securin does not protect separase from destruction, and it does not strengthen cohesin. It has no hold on cyclin B, which is a separate APC/C target.`,
  },
  [r`State Knudson's two-hit hypothesis using retinoblastoma as the example.`]: {
    question: r`One child develops retinoblastoma in both eyes at 10 months. Another develops a single tumor in one eye at age 5 and has no family history. What best explains the first child's pattern?`,
    options: [r`He inherited two mutant RB1 alleles, so each tumor needed no somatic hit`, r`He inherited no mutant RB1 allele, so each tumor needed two somatic hits`, r`He inherited one RB1 oncogene allele, so no tumor needed any further hit`, r`He inherited one mutant RB1 allele, so each tumor needed one somatic hit`],
    correctAnswer: 3,
    explanation: r`A tumor suppressor needs both alleles inactivated. With one germline hit already in every retinal cell, a single somatic hit is enough, so tumors arise early and in both eyes. Two somatic hits in one cell is the rare sporadic route (late, one eye). RB1 is not an oncogene, and inheriting two mutant alleles is not the familial pattern.`,
  },
  [r`What are chiasmata, and what mechanical job do they perform?`]: {
    question: r`In a mutant, meiotic chromosomes pair and replicate normally but no crossovers form, so no chiasmata are present at metaphase I. What is the most likely consequence?`,
    options: [r`Sisters are not linked, so they segregate at random in meiosis I`, r`Homologs are not linked, so they segregate at random in meiosis I`, r`Homologs are not linked, so they segregate at random in meiosis II`, r`Sisters are not linked, so they segregate at random in meiosis II`],
    correctAnswer: 1,
    explanation: r`Chiasmata, with arm cohesion, hold the two homologs together as one bivalent so the meiosis I spindle can attach them to opposite poles. Without them the homologs behave as unconnected units and often go to the same pole. Sister chromatids are held by cohesin, not chiasmata, and homologs separate in meiosis I, not II.`,
  },
  [r`A trisomic individual whose extra chromosome carries two different parental alleles indicates nondisjunction in meiosis {{c1::I}}.`]: {
    question: r`At a marker next to the centromere of chromosome 21, a mother has alleles 3 and 5 and a father has alleles 7 and 9. Their child with trisomy 21 has alleles 3, 5 and 7. Where did nondisjunction occur?`,
    options: [r`In the mother, at meiosis I`, r`In the mother, at meiosis II`, r`In the father, at meiosis I`, r`In the father, at meiosis II`],
    correctAnswer: 0,
    explanation: r`The child received two chromosomes from the mother (3 and 5), so the error was maternal. They carry DIFFERENT alleles, so they are the two homologs, which should have separated in meiosis I. A meiosis II error would give two identical copies, such as 3 and 3. The father contributed only one allele, so his meiosis was normal.`,
  },
  [r`Oncogenic mutations act {{c1::dominantly — one mutant allele suffices}}, while tumor suppressors require loss of both alleles.`]: {
    question: r`A tumor cell is fused with a normal cell of the same type. The hybrid cell, which contains both genomes, still divides without control. What does this show about the tumor's driver mutation?`,
    options: [r`It is dominant, as expected for an activated oncogene`, r`It is recessive, as expected for an activated oncogene`, r`It is dominant, as expected for a lost tumor suppressor`, r`It is recessive, as expected for a lost tumor suppressor`],
    correctAnswer: 0,
    explanation: r`The normal genome's alleles could not restore control, so the mutant allele acts dominantly: one hyperactive copy is enough. That is the oncogene pattern. If the tumor had instead lost both copies of a tumor suppressor (a recessive defect), the normal cell's working copies would have supplied the brake and the hybrid would behave normally.`,
  },
  [r`Oncogenic {{c1::Ras}} mutations impair GTP hydrolysis, locking the protein in its active GTP-bound state.`]: {
    question: r`In a tumor, Ras binds GTP normally but hydrolyzes it at 1% of the normal rate, and GAP proteins cannot speed it up. Which treatment would still be expected to slow these cells' proliferation?`,
    options: [r`A MEK inhibitor, which acts downstream of the mutant Ras`, r`A receptor blocker, which acts upstream of the mutant Ras`, r`A GAP activator, which acts to switch off the mutant Ras`, r`A growth factor trap, which acts to starve the mutant Ras`],
    correctAnswer: 0,
    explanation: r`Mutant Ras is locked in its GTP-bound active state and signals through Raf, MEK and ERK without any growth factor. Only a block downstream of Ras, such as at MEK, interrupts the signal. Blocking receptors or removing growth factors acts upstream of a switch that is already stuck on, and GAPs cannot switch this Ras off.`,
  },
  [r`BRCA1 and BRCA2: oncogenes or tumor suppressors, and what pathway do they serve?`]: {
    question: r`A woman inherits one mutant BRCA1 allele. Her breast tumor has lost the second, normal allele, and its cells mend double-strand breaks inaccurately. How is BRCA1 best described?`,
    options: [r`A tumor suppressor in growth factor receptor signaling`, r`A tumor suppressor in homologous recombination repair`, r`An oncogene in homologous recombination repair`, r`An oncogene in growth factor receptor signaling`],
    correctAnswer: 1,
    explanation: r`Cancer appears only after BOTH alleles are lost, which is the tumor suppressor (loss-of-function) pattern, not the single dominant hit of an oncogene. BRCA1 works in homologous recombination, the accurate repair of double-strand breaks, so its loss leaves error-prone repair. It is not part of growth factor signaling.`,
  },
  [r`How does the cell exit mitosis after chromatids separate?`]: {
    question: r`After anaphase, a cell destroys cyclin B and inactivates CDK1 normally, but the phosphatases that reverse MPF's phosphorylations are inhibited. What is the most direct consequence?`,
    options: [r`Cohesin stays intact, so the sister chromatids cannot separate`, r`Lamins stay phosphorylated, so the nuclear envelope cannot re-form`, r`Cyclin B stays abundant, so the CDK1 kinase cannot be shut off`, r`Securin stays stable, so the separase enzyme cannot be released`],
    correctAnswer: 1,
    explanation: r`Exit from mitosis needs two steps: CDK1 is switched off by cyclin B destruction, and phosphatases then remove the phosphates MPF added. Without the second step lamins remain phosphorylated and the envelope cannot reassemble. The other options describe events that have already happened normally here: sister separation, securin loss and cyclin B loss.`,
  },
  [r`What exactly does separase cleave to trigger anaphase?`]: {
    question: r`Cells express a cohesin whose Scc1 (Rad21) subunit has a mutated separase cut site. APC/C-Cdc20 is activated normally once all kinetochores are attached. What happens?`,
    options: [r`Securin and cyclin B are preserved, and sister chromatids stay joined`, r`Securin and cyclin B are destroyed, and sister chromatids pull apart`, r`Securin and cyclin B are preserved, but sister chromatids pull apart`, r`Securin and cyclin B are destroyed, but sister chromatids stay joined`],
    correctAnswer: 3,
    explanation: r`Separase triggers anaphase by cutting the Scc1 (kleisin) subunit, which opens the cohesin ring. With an uncuttable Scc1 the upstream steps still run, so APC/C destroys securin and cyclin B, but the ring stays closed and sisters stay together. Preserved securin would require a block at APC/C, which is working here.`,
  },
  [r`In meiosis I, {{c1::shugoshin}} protects centromeric cohesin from separase, so only arm cohesin is cleaved.`]: {
    question: r`In an experiment, shugoshin is kept at the centromeres through meiosis II instead of being removed after meiosis I. What is the expected outcome?`,
    options: [r`Homologs fail to separate at anaphase I, but sisters separate at anaphase II`, r`Sisters separate early at anaphase I, then segregate at random at anaphase II`, r`Homologs separate at anaphase I, but sisters fail to separate at anaphase II`, r`Homologs separate at anaphase I, and sisters separate normally at anaphase II`],
    correctAnswer: 2,
    explanation: r`Shugoshin shields centromeric cohesin from separase. That is correct in meiosis I, where only arm cohesin is cut and homologs separate, but if the shield persists, centromeric cohesin also cannot be cut at anaphase II and sisters stay joined. Early sister separation is what happens when shugoshin is missing, not when it persists.`,
  },
  [r`Crossing over occurs during {{c1::pachytene}} of prophase I, when the synaptonemal complex fully joins homologs.`]: {
    question: r`A spermatocyte is fixed at the moment the synaptonemal complex runs the full length of every pair of homologs. Which substage is this, and what is happening?`,
    options: [r`Pachytene, with crossing over between two sister chromatids`, r`Diplotene, with crossing over between non-sister chromatids`, r`Pachytene, with crossing over between non-sister chromatids`, r`Zygotene, with crossing over between two sister chromatids`],
    correctAnswer: 2,
    explanation: r`Complete synapsis defines pachytene, and that is when crossing over takes place between non-sister chromatids of the two homologs. In zygotene synapsis is only beginning, and in diplotene the complex has dissolved to reveal chiasmata. Exchange between sister chromatids would not create new allele combinations.`,
  },
  [r`Order the five substages of meiotic prophase I.`]: {
    question: r`In a cell in meiotic prophase I, the synaptonemal complex has just dissolved, and the homologs are held together only at chiasmata that are now visible. Which substage is this, and which comes next?`,
    options: [r`Diplotene, followed by pachytene`, r`Pachytene, followed by diplotene`, r`Diplotene, followed by diakinesis`, r`Zygotene, followed by pachytene`],
    correctAnswer: 2,
    explanation: r`The order is leptotene, zygotene, pachytene, diplotene, diakinesis. Dissolving of the complex with chiasmata visible marks diplotene, and diakinesis (final condensation and envelope breakdown) follows. Pachytene comes before diplotene and is the stage of full synapsis, and zygotene is when synapsis is only starting.`,
  },
  [r`What separates at anaphase I vs anaphase II vs mitotic anaphase?`]: {
    question: r`An animal has a diploid number of 6. In one dividing cell, 3 single-chromatid chromosomes are moving to each pole. Which anaphase is this, and what kind of division is it?`,
    options: [r`Anaphase II, a reductional division`, r`Anaphase II, an equational division`, r`Anaphase I, a reductional division`, r`Mitotic anaphase, an equational division`],
    correctAnswer: 1,
    explanation: r`Single chromatids moving apart means sisters are separating, which happens in anaphase II and mitotic anaphase, both equational. Only 3 per pole means the cell was already haploid, so it is anaphase II; mitosis would send 6 to each pole. Anaphase I is the reductional one, and there each chromosome still has two chromatids.`,
  },
  [r`Classify Myc, HER2, and Bcr-Abl, and give each one's mechanism in a phrase.`]: {
    question: r`A patient's leukemia cells carry a translocation between chromosomes 9 and 22. Which oncogene product does this create, and how does it act?`,
    options: [r`HER2, a receptor tyrosine kinase that is present in excess`, r`Myc, a transcription factor that is produced in great excess`, r`Bcr-Abl, a fusion transcription factor that is fully deleted`, r`Bcr-Abl, a fusion tyrosine kinase that is active all the time`],
    correctAnswer: 3,
    explanation: r`The t(9;22) Philadelphia chromosome joins BCR to ABL and produces a kinase that signals constantly, the driver of chronic myeloid leukemia. HER2 is an amplified receptor typical of breast cancer, and Myc is an overexpressed transcription factor. Bcr-Abl is a kinase gained by fusion, not a transcription factor that is lost.`,
  },
  [r`Li-Fraumeni syndrome is caused by an inherited mutation in {{c1::TP53 (p53)}}.`]: {
    question: r`A woman with Li-Fraumeni syndrome has had two unrelated cancers by age 30. Which gene is affected, and what do her non-tumor cells carry?`,
    options: [r`TP53; her normal cells keep no working copy`, r`RB1; her normal cells keep one working copy`, r`RAS; her normal cells hold one overactive copy`, r`TP53; her normal cells keep one working copy`],
    correctAnswer: 3,
    explanation: r`Li-Fraumeni syndrome is an inherited mutation in one TP53 allele. Every cell starts with a single working copy, and a tumor arises where a somatic hit removes it, the two-hit pattern of a tumor suppressor. Inherited RB1 mutation causes retinoblastoma, and RAS is an oncogene that is activated somatically.`,
  },
  [r`If nondisjunction occurs in meiosis I, what is the gamete outcome?`]: {
    question: r`In one spermatocyte, chromosome 21 undergoes nondisjunction in meiosis I, and meiosis II is normal. Each of the four sperm fertilizes a normal egg. What do the four zygotes have?`,
    options: [r`One has trisomy 21, one has monosomy 21, two are normal`, r`Two have trisomy 21 and two have monosomy 21`, r`Two have trisomy 21 and two are fully normal`, r`Four have trisomy 21 and none has monosomy 21`],
    correctAnswer: 1,
    explanation: r`A meiosis I error sends both homologs to one cell and none to the other, so after meiosis II two gametes are n+1 and two are n-1, and none is normal. With normal eggs that gives two trisomies and two monosomies. Two normal products with one n+1 and one n-1 is the result of a meiosis II error.`,
  },
  [r`Which cyclin-CDK complex begins phosphorylating Rb in mid-G1 in response to growth-factor signaling?`]: {
    question: r`Cells with normal Rb are given growth factor, but a mutation prevents them from making the one cyclin that growth factor signaling induces directly. Which complex fails to form, and what is the result?`,
    options: [r`Cyclin D-CDK4/6; Rb phosphorylation never begins`, r`Cyclin E-CDK2; Rb phosphorylation never begins`, r`Cyclin A-CDK2; replication origins never fire`, r`Cyclin B-CDK1; nuclear lamins never dissolve`],
    correctAnswer: 0,
    explanation: r`Growth factors induce cyclin D, and cyclin D-CDK4/6 makes the first phosphorylations of Rb in mid-G₁. Cyclin E-CDK2 only completes the job afterward and is induced by E2F, not directly by growth factors. Cyclin A-CDK2 and cyclin B-CDK1 act later, in S phase and at mitosis.`,
  },
  [r`{{c1::Cyclin E-CDK2}} completes Rb hyperphosphorylation at the G1/S transition, fully releasing E2F.`]: {
    question: r`Cells are given growth factor just long enough for cyclin E-CDK2 to become active, and then the growth factor is removed. The cells enter S phase anyway. What explains this?`,
    options: [r`E2F drives cyclin D transcription, which keeps Rb phosphorylated`, r`Rb drives cyclin E transcription, which keeps E2F phosphorylated`, r`p21 drives cyclin E transcription, which keeps Rb phosphorylated`, r`E2F drives cyclin E transcription, which keeps Rb phosphorylated`],
    correctAnswer: 3,
    explanation: r`Cyclin E-CDK2 completes Rb phosphorylation and frees E2F, and E2F in turn transcribes more cyclin E. This positive feedback loop sustains itself without growth factors, which makes S-phase entry irreversible. Cyclin D depends on growth factors, Rb is the target and not the activator, and p21 inhibits CDKs.`,
  },
  [r`Why must centromeric cohesion survive anaphase I?`]: {
    question: r`In an oocyte at metaphase II, single unpaired chromatids are scattered on the spindle instead of pairs of sister chromatids. What went wrong earlier, and what follows?`,
    options: [r`Centromeric cohesin was kept at anaphase I, so sisters segregate at random`, r`Chromosome arm cohesin was lost at anaphase I, so homologs fail to separate`, r`Chromosome arm cohesin was kept at anaphase I, so sisters segregate at random`, r`Centromeric cohesin was lost at anaphase I, so sisters segregate at random`],
    correctAnswer: 3,
    explanation: r`Sisters must stay joined at their centromeres through meiosis I so they can attach to opposite poles in meiosis II. If that cohesion is lost early, the single chromatids have no partner to orient against and go to either pole, giving aneuploid gametes. Loss of arm cohesin at anaphase I is normal and is what lets homologs separate.`,
  },
  [r`In a trisomy case, what allele pattern implicates meiosis II nondisjunction?`]: {
    question: r`At a marker next to a centromere, a father has alleles 2 and 4 and a mother has alleles 6 and 8. Nondisjunction of this chromosome occurs in the father's meiosis II. Which set of alleles would a trisomic child carry?`,
    options: [r`Alleles 2, 4 and 6`, r`Alleles 2, 6 and 8`, r`Alleles 2, 2 and 6`, r`Alleles 6, 6 and 2`],
    correctAnswer: 2,
    explanation: r`A meiosis II error fails to separate sister chromatids, which are identical, so the father gives two copies of the same allele (2 and 2) and the mother gives one (6). Alleles 2 and 4 together are his two homologs, a meiosis I error. Two maternal alleles, whether 6 and 8 or 6 and 6, would place the error in the mother.`,
  },
  [r`In G1, hypophosphorylated {{c1::Rb}} binds E2F transcription factors, blocking transcription of S-phase genes.`]: {
    question: r`A cell line lacks Rb protein entirely. The cells are placed in medium with no growth factors. What happens to E2F and to S-phase genes?`,
    options: [r`E2F is bound, so the S-phase genes stay silent without mitogens`, r`E2F is free, so the S-phase genes are transcribed without mitogens`, r`E2F is degraded, so the S-phase genes stay silent without mitogens`, r`E2F is free, but the S-phase genes stay silent without mitogens`],
    correctAnswer: 1,
    explanation: r`Rb is the brake that holds E2F in G₁. With no Rb, nothing sequesters E2F, so it turns on S-phase genes whether or not growth factors are present. Growth factors normally matter only because they lead to Rb phosphorylation, so free E2F does not need them. E2F is not degraded when Rb is absent.`,
  },
  [r`When damage is irreparable, which pro-apoptotic genes does p53 transactivate?`]: {
    question: r`After a lethal dose of radiation, a thymocyte with normal p53 releases cytochrome c from its mitochondria within hours. Which p53 target genes account for this, and how?`,
    options: [r`p21 and MDM2, which permeabilize the mitochondrial outer membrane`, r`Bax and PUMA, which bind death receptors on the plasma membrane`, r`Bax and PUMA, which permeabilize the mitochondrial outer membrane`, r`Bcl-2 and Bcl-xL, which permeabilize the mitochondrial outer membrane`],
    correctAnswer: 2,
    explanation: r`When damage cannot be repaired, p53 switches on the pro-apoptotic Bcl-2 family genes Bax and PUMA, which open the mitochondrial outer membrane and start the intrinsic pathway. p21 causes arrest and MDM2 degrades p53; neither kills. Bcl-2 and Bcl-xL are anti-apoptotic, and death receptors belong to the extrinsic pathway.`,
  },
  [r`What does the spindle assembly checkpoint monitor, and through which proteins does it signal?`]: {
    question: r`In a dividing human cell, 45 chromosomes are correctly attached to the spindle but one kinetochore on the last chromosome has no microtubules. What happens?`,
    options: [r`Mad2 and BubR1 activate APC/C-Cdc20, so the whole cell begins anaphase`, r`ATM and Chk2 inhibit the Cdc25 enzyme, so the whole cell delays anaphase`, r`Mad2 and BubR1 inhibit APC/C-Cdc20, so the whole cell delays anaphase`, r`Mad2 and BubR1 hold that one chromosome while the other 45 separate`],
    correctAnswer: 2,
    explanation: r`The spindle assembly checkpoint watches kinetochore attachment, and a single unattached kinetochore makes a Mad2/BubR1 signal that inhibits APC/C-Cdc20 for the whole cell. No chromosome separates until all are attached. ATM, Chk2 and Cdc25 belong to the DNA damage response, which is not triggered here.`,
  },
  [r`What does cyclin A-CDK2 do during S phase?`]: {
    question: r`A human cell licenses thousands of replication origins in G₁ and still finishes S phase with exactly double its DNA. Which activity ensures that no origin is used twice?`,
    options: [r`Cyclin D-CDK4, which fires licensed origins and blocks re-licensing`, r`Cyclin B-CDK1, which licenses the origins and blocks their firing`, r`Cyclin A-CDK2, which licenses each origin again after it has fired`, r`Cyclin A-CDK2, which fires licensed origins and blocks re-licensing`],
    correctAnswer: 3,
    explanation: r`In S phase cyclin A-CDK2 triggers firing of origins that were licensed in G₁ and at the same time prevents new licensing, so each origin fires once per cycle. Re-licensing after firing would cause re-replication, the opposite of what is seen. Cyclin D-CDK4 acts on Rb in G₁ and cyclin B-CDK1 drives mitosis.`,
  },
  [r`What two proteins make up MPF, and what transition does it drive?`]: {
    question: r`A frog oocyte is arrested in G₂. A small volume of cytoplasm from an M-phase egg is injected into it. Which complex in that cytoplasm matters, and what does the oocyte do?`,
    options: [r`Cyclin B-CDK1; the oocyte returns to S phase`, r`Cyclin E-CDK2; the oocyte enters M phase`, r`Cyclin B-CDK1; the oocyte enters M phase`, r`Cyclin D-CDK4; the oocyte returns to G₁ phase`],
    correctAnswer: 2,
    explanation: r`M-phase cytoplasm contains active MPF, which is cyclin B bound to CDK1, and MPF drives the G₂-to-M transition in the recipient. The cycle does not run backward to S or G₁. Cyclin E-CDK2 and cyclin D-CDK4 are the G₁ and G₁/S complexes and do not trigger mitosis.`,
  },
  [r`{{c1::Wee1}} kinase holds CDK1 inactive by adding inhibitory phosphates, keeping MPF off until G2 ends.`]: {
    question: r`A strain of fission yeast has lost all Wee1 kinase activity. Compared with normal cells, how do these cells divide?`,
    options: [r`They enter mitosis late and divide at a larger size`, r`They arrest in G₂ and cannot divide at any size`, r`They skip S phase and divide without copying DNA`, r`They enter mitosis early and divide at a smaller size`],
    correctAnswer: 3,
    explanation: r`Wee1 adds inhibitory phosphates to CDK1 and so delays mitosis. Without this brake MPF switches on sooner, and cells divide before they have grown to normal size. Late entry at a large size or G₂ arrest is what losing the opposing phosphatase, Cdc25, would cause. Wee1 has no role in S phase.`,
  },
  [r`The phosphatase {{c1::Cdc25}} removes inhibitory phosphates from CDK1, switching on MPF and triggering mitotic entry.`]: {
    question: r`A cell extract contains cyclin B-CDK1 complexes that carry an inhibitory phosphate on tyrosine 15 and have no kinase activity. Which addition would activate them?`,
    options: [r`Cdc25, a phosphatase that removes the inhibitory phosphate`, r`Wee1, a phosphatase that removes the inhibitory phosphate`, r`Cdc25, a kinase that adds a second activating phosphate`, r`Cyclin B, a subunit that displaces the inhibitory phosphate`],
    correctAnswer: 0,
    explanation: r`Cdc25 is the phosphatase that strips the inhibitory phosphates from CDK1 and switches MPF on. Wee1 is the kinase that put them there, so adding it keeps MPF off. Cdc25 is not a kinase, and extra cyclin B does not help because the complexes already have cyclin B bound.`,
  },
  [r`p53 arrests the cell cycle by inducing transcription of {{c1::p21}}, a broad CDK inhibitor.`]: {
    question: r`Cells have normal p53, but both copies of the p21 gene are deleted. The cells are irradiated in G₁. What happens?`,
    options: [r`p53 stays low, so cyclin E-CDK2 stays active and the cells enter S phase`, r`p53 rises, so cyclin E-CDK2 is inhibited and the cells arrest in G₁`, r`p53 rises, but cyclin E-CDK2 stays active and the cells enter S phase`, r`p53 rises, but cyclin B-CDK1 is destroyed and the cells arrest in M`],
    correctAnswer: 2,
    explanation: r`p53 is stabilized normally by the damage, but it stops the cycle through p21, the CDK inhibitor it transcribes. With no p21, cyclin E-CDK2 is not inhibited, Rb is phosphorylated and the cells go on into S phase. p53 levels do not depend on p21, and the arrest in question is at G₁/S, not in mitosis.`,
  },
  [r`Name two structural substrates MPF phosphorylates to remodel the cell for mitosis.`]: {
    question: r`Cells express nuclear lamins in which the sites phosphorylated by MPF are changed to alanine. Condensin is normal. What is seen when MPF becomes active?`,
    options: [r`The nuclear envelope dissolves, but chromosomes stay diffuse`, r`Chromosomes condense, but the nuclear envelope stays intact`, r`Chromosomes stay diffuse and the nuclear envelope stays intact`, r`Chromosomes condense and the nuclear envelope dissolves early`],
    correctAnswer: 1,
    explanation: r`MPF phosphorylates lamins to take apart the lamina and envelope, and separately phosphorylates condensin to compact the chromosomes. Lamins that cannot be phosphorylated keep the envelope intact, while condensin still works. Diffuse chromosomes would need a condensin defect, and nothing here speeds envelope breakdown.`,
  },
  [r`DNA damage is sensed by the kinases {{c1::ATM and ATR}}, which then phosphorylate the checkpoint kinases Chk2 and Chk1.`]: {
    question: r`Hydroxyurea stalls replication forks and leaves long stretches of single-stranded DNA. Which sensor kinase responds mainly to this lesion, and which checkpoint kinase does it then activate?`,
    options: [r`ATM, which then activates Chk2`, r`ATR, which then activates Cdc25`, r`MDM2, which then activates p53`, r`ATR, which then activates Chk1`],
    correctAnswer: 3,
    explanation: r`ATR responds to single-stranded DNA at stalled forks and phosphorylates Chk1. ATM with Chk2 is the arm that responds mainly to double-strand breaks. Cdc25 is inhibited, not activated, by this pathway, and MDM2 is a ubiquitin ligase that destroys p53, not a damage sensor.`,
  },
  [r`Mechanistically, how do Chk1/Chk2 impose G2 arrest after DNA damage?`]: {
    question: r`Cells express a Cdc25 that cannot be phosphorylated by Chk1 or Chk2. Their DNA is damaged during G₂. What happens?`,
    options: [r`Cdc25 stays inactive, CDK1 keeps its phosphates and cells stay in G₂`, r`Cdc25 stays active, CDK1 keeps its phosphates and cells stay in G₂`, r`Cdc25 stays inactive, CDK1 loses its phosphates and cells enter mitosis`, r`Cdc25 stays active, CDK1 loses its phosphates and cells enter mitosis`],
    correctAnswer: 3,
    explanation: r`Chk1 and Chk2 impose G₂ arrest by phosphorylating and inhibiting Cdc25, which leaves the inhibitory phosphates on CDK1. A Cdc25 that escapes this stays active, strips those phosphates and turns on MPF, so cells enter mitosis with damaged DNA. Active Cdc25 and phosphorylated CDK1 cannot go together, since removing those phosphates is what Cdc25 does.`,
  },
  [r`In unstressed cells, p53 is kept at low levels by {{c1::MDM2}}, an E3 ubiquitin ligase.`]: {
    question: r`A small molecule occupies the pocket on MDM2 that binds p53. It is added to undamaged cells with normal p53. What happens?`,
    options: [r`p53 is destroyed faster and p21 falls without any DNA damage`, r`p53 is unchanged, because only DNA damage can stabilize it`, r`p53 accumulates but is inactive until MDM2 ubiquitinates it`, r`p53 accumulates and p21 is induced without any DNA damage`],
    correctAnswer: 3,
    explanation: r`MDM2 is the E3 ubiquitin ligase that keeps p53 low by sending it to the proteasome. Blocking the MDM2-p53 contact has the same effect as damage-induced phosphorylation of p53: p53 is spared, builds up and transcribes targets such as p21. Ubiquitination by MDM2 destroys p53; it does not activate it.`,
  },
  [r`Contrast the two families of CDK inhibitors: INK4 vs Cip/Kip.`]: {
    question: r`Two purified CDK inhibitors are tested. Inhibitor X blocks only cyclin D-CDK4/6. Inhibitor Y blocks cyclin D-CDK4/6, cyclin E-CDK2 and cyclin A-CDK2. Which identification fits?`,
    options: [r`X is an INK4 protein such as p16; Y is a Cip/Kip protein such as p21`, r`X is a Cip/Kip protein such as p21; Y is an INK4 protein such as p16`, r`X is an INK4 protein such as p21; Y is a Cip/Kip protein such as p16`, r`X is a Cip/Kip protein such as p16; Y is an INK4 protein such as p27`],
    correctAnswer: 0,
    explanation: r`INK4 proteins, of which p16 is the example, are specific for CDK4/6-cyclin D. Cip/Kip proteins (p21, p27) inhibit a broad range of cyclin-CDK complexes. The wrong choices either swap the two families or attach p16 and p21 to the wrong family.`,
  },
  [r`Cells in S phase are identified by incorporating {{c1::BrdU or tritiated thymidine}}, because thymidine is used for DNA but not RNA.`]: {
    question: r`A student wants to mark S-phase cells but uses tritiated uridine instead of tritiated thymidine. After a brief pulse nearly every interphase cell is labeled. Why?`,
    options: [r`Uridine goes into DNA, which is made all through interphase`, r`Thymidine goes into RNA, which is made only in the S phase`, r`Uridine goes into RNA, which is made all through interphase`, r`Uridine goes into protein, which is made all through the cycle`],
    correctAnswer: 2,
    explanation: r`Thymidine is used for DNA but not RNA, so it marks only cells that are replicating DNA. Uridine is an RNA precursor, and transcription goes on through all of interphase, so it labels almost every cell. DNA is made only in S phase, and nucleosides are not built into protein.`,
  },
  [r`A patient has 45,X in half her cells and 46,XX in the rest. Was the error meiotic or mitotic, and how can you tell?`]: {
    question: r`One girl has an extra chromosome 21 in every cell tested from blood and skin. A second girl has it in only 20% of her cells, and the rest are 46,XX. When did each error most likely occur?`,
    options: [r`First girl: in a mitosis after fertilization; second girl: in meiosis, before it`, r`Both girls: in meiosis before fertilization, in meiosis I and then in meiosis II`, r`Both girls: in a mitosis after fertilization, in the egg and then in the sperm`, r`First girl: in meiosis, before fertilization; second girl: in a mitosis after it`],
    correctAnswer: 3,
    explanation: r`An error in meiosis is carried by the gamete, so the zygote and every cell descended from it have it. A mixture of normal and abnormal cell lines (mosaicism) means the zygote was one karyotype and a later mitotic error created the second line. Meiosis I and meiosis II errors both affect every cell, so neither gives a mosaic.`,
  },
  [r`{{c1::Quiescence}} (G0) is reversible when growth factors return, whereas {{c2::senescence}} is a permanent arrest enforced by p16 and p53.`]: {
    question: r`Culture A stopped dividing after its serum was removed. Culture B stopped dividing after many passages, when its telomeres became critically short. Fresh serum is added to both. What happens?`,
    options: [r`B re-enters the cycle; A stays arrested with high p16`, r`A re-enters the cycle; B stays arrested with high p16`, r`Both re-enter the cycle as growth factors return`, r`Neither re-enters; both have left the cycle for good`],
    correctAnswer: 1,
    explanation: r`Culture A is quiescent (G₀), a reversible rest that ends when growth factors return. Culture B is senescent: telomere attrition has triggered a permanent arrest enforced by p16 and p53, and growth factors cannot reverse it. Treating both as reversible or both as permanent misses the difference between the two states.`,
  },
  [r`In a flow cytometry DNA histogram, what do the 2N and 4N peaks represent, and what lies between them?`]: {
    question: r`A DNA-content histogram is made from an asynchronous culture. Where do a cell in metaphase and a cell in telophase that has not yet completed cytokinesis appear?`,
    options: [r`Both in the 2N peak, together with the G₁ cells`, r`Metaphase in the 4N peak, telophase in the 2N peak`, r`Both in the 4N peak, together with the G₂ cells`, r`Both between the peaks, together with S-phase cells`],
    correctAnswer: 2,
    explanation: r`The assay measures DNA per cell. Until cytokinesis is finished a mitotic cell still holds all its replicated DNA, so every stage of mitosis counts as 4N and cannot be told apart from G₂. Only after division do the daughters fall in the 2N peak, and the region between the peaks is S phase.`,
  },
  [r`A compound makes cells pile up at 4N DNA content with no increase in the region between peaks. What does it block?`]: {
    question: r`Drug P makes cells pile up at 4N DNA content, with almost none between the peaks. Drug Q makes cells pile up between the 2N and 4N peaks. What does each drug block?`,
    options: [r`P stalls DNA replication; Q blocks the G₂/M step, after replication`, r`P blocks the G₂/M step, after replication; Q stalls DNA replication`, r`P blocks the G₁/S step, before replication; Q stalls DNA replication`, r`P blocks the G₂/M step, after replication; Q blocks the G₁/S step`],
    correctAnswer: 1,
    explanation: r`Cells at 4N have finished replication but not divided, so P blocks entry into or passage through mitosis, as a CDK1 inhibitor or spindle poison would. Cells stuck between the peaks have partly replicated DNA, so Q acts in S phase. A G₁/S block would instead collect cells in the 2N peak.`,
  },
  [r`In a 24-hour cycle, G1 lasts about {{c1::11}} hours, S about 8, G2 about 4, and M about {{c2::1}} hour.`]: {
    question: r`A mammalian cell line has a typical 24-hour cycle in which S phase takes 8 hours and G₂ takes 4. In a steadily growing asynchronous culture, about what fraction of cells are in G₁ and in mitosis?`,
    options: [r`About 46% in G₁ and about 4% in M`, r`About 33% in G₁ and about 17% in M`, r`About 25% in G₁ and about 25% in M`, r`About 4% in G₁ and about 46% in M`],
    correctAnswer: 0,
    explanation: r`S and G₂ use 12 hours, and of the other 12 mitosis takes only about 1 hour and G₁ about 11. The fraction of cells in a phase is roughly its share of the cycle: 11/24 is about 46% and 1/24 is about 4%. The other choices give mitosis several hours or split the remaining time evenly, but M is the shortest phase.`,
  },
  [r`The Rb pathway is disrupted in nearly every human cancer. How can a tumor achieve that without mutating RB1 itself?`]: {
    question: r`A tumor has two normal RB1 alleles, yet its Rb protein is hyperphosphorylated at all times and E2F is always free. Which lesion could explain this?`,
    options: [r`Amplification of p16, which inhibits CDK4/6`, r`Amplification of cyclin D, which drives CDK4/6`, r`Deletion of CDK4, which phosphorylates Rb in G₁`, r`Deletion of E2F, which Rb normally binds in G₁`],
    correctAnswer: 1,
    explanation: r`Rb can be disabled without mutating it by overdriving its kinase: extra cyclin D (or CDK4) keeps Rb phosphorylated so it cannot hold E2F. Extra p16 or loss of CDK4 would do the reverse and keep Rb active. Deleting E2F would not phosphorylate Rb and would remove the factor that drives S phase.`,
  },
  [r`Independent assortment of 23 chromosome pairs alone yields {{c1::$2^{23}$}} (about 8.4 million) possible gametes, before crossing over is counted.`]: {
    question: r`A plant has a diploid number of 8. Counting only independent assortment, with no crossing over, how many genetically different gametes can one individual produce?`,
    options: [r`8 different gametes`, r`16 different gametes`, r`64 different gametes`, r`256 different gametes`],
    correctAnswer: 1,
    explanation: r`Each homologous pair lines up independently at metaphase I and can orient two ways, so the count is 2 raised to the number of PAIRS. A diploid number of 8 is 4 pairs, giving 2⁴ = 16. Using 8 as the exponent gives 256, squaring 8 gives 64, and 8 is just the chromosome number.`,
  },
  [r`Aneuploid daughters implicate the {{c1::spindle assembly}} checkpoint; mutations accumulating after radiation implicate the {{c2::DNA damage}} checkpoints.`]: {
    question: r`Line 1 cells have normal DNA sequence, but their daughters often have 45 or 47 chromosomes. Line 2 cells keep 46 chromosomes but pile up mutations after each dose of radiation. Which checkpoint has failed in each?`,
    options: [r`Line 1: a DNA damage checkpoint; line 2: the spindle assembly checkpoint`, r`Line 1: the spindle assembly checkpoint; line 2: the same spindle checkpoint`, r`Line 1: a DNA damage checkpoint; line 2: another DNA damage checkpoint`, r`Line 1: the spindle assembly checkpoint; line 2: a DNA damage checkpoint`],
    correctAnswer: 3,
    explanation: r`Gaining or losing whole chromosomes means anaphase began with a chromosome unattached, a spindle assembly checkpoint failure. Mutations that persist after radiation mean cells replicated or divided without stopping for repair, a DNA damage checkpoint failure. Each checkpoint watches one problem, so one failure cannot explain both lines.`,
  },
  [r`Hydroxyurea and nocodazole are both used to synchronize cultures. Where does each arrest cells, and by what mechanism?`]: {
    question: r`One culture is arrested with hydroxyurea and another with nocodazole. Deoxynucleosides, which cells can convert to dNTPs, are then added to both. Which arrest is relieved, and why?`,
    options: [r`The nocodazole arrest, because ribonucleotide reductase is bypassed`, r`The hydroxyurea arrest, because the microtubules can now polymerize`, r`The hydroxyurea arrest, because ribonucleotide reductase is bypassed`, r`The nocodazole arrest, because the spindle checkpoint is now satisfied`],
    correctAnswer: 2,
    explanation: r`Hydroxyurea inhibits ribonucleotide reductase, so cells stall in S phase for lack of dNTPs; supplying deoxynucleosides by another route lets replication resume. Nocodazole depolymerizes microtubules and holds cells in mitosis through the spindle checkpoint, which nucleotides do nothing to fix.`,
  },
  [r`Classify neurons, hepatocytes, and intestinal crypt cells with respect to G0, and connect this to healing.`]: {
    question: r`Biopsies from a healthy, uninjured adult are given a brief pulse of BrdU. What labeling pattern is expected?`,
    options: [r`Crypt cells: very few labeled; hepatocytes: many; neurons: none`, r`Crypt cells: many labeled; hepatocytes: none; neurons: very few`, r`Crypt cells: many labeled; hepatocytes: very few; neurons: none`, r`Crypt cells: none labeled; hepatocytes: very few; neurons: many`],
    correctAnswer: 2,
    explanation: r`Intestinal crypt cells are labile and cycle constantly, so many are in S phase. Hepatocytes are stable cells resting in G₀ that divide only occasionally unless the liver is injured. Neurons are permanent cells that never re-enter the cycle, so they are not labeled at all.`,
  },
  [r`Human oocytes arrest in {{c1::prophase I}} from fetal life until ovulation, then arrest again in {{c2::metaphase II}} until fertilization.`]: {
    question: r`An oocyte is examined in the ovary of a 5-year-old girl, and another is examined just after ovulation in a 25-year-old woman, before any sperm arrives. At what stage is each one arrested?`,
    options: [r`Girl: prophase I; ovulated oocyte: metaphase II`, r`Girl: metaphase II; ovulated oocyte: prophase I`, r`Girl: G₁ phase; ovulated oocyte: prophase I`, r`Girl: prophase I; ovulated oocyte: telophase II`],
    correctAnswer: 0,
    explanation: r`Oocytes begin meiosis before birth and wait in prophase I through childhood. At ovulation the oocyte finishes meiosis I and stops again at metaphase II, and it completes meiosis II only if it is fertilized. Reaching telophase II without a sperm therefore does not happen, and a childhood oocyte is past G₁.`,
  },
  [r`Why does conventional chemotherapy predictably cause myelosuppression, mucositis, and hair loss?`]: {
    question: r`A new drug kills cells only while they are replicating DNA. Which pairing correctly predicts a normal tissue it will injure and one it will spare?`,
    options: [r`Injured: bone marrow; spared: cardiac muscle`, r`Injured: cardiac muscle; spared: bone marrow`, r`Injured: brain neurons; spared: gut epithelium`, r`Injured: skeletal muscle; spared: hair follicles`],
    correctAnswer: 0,
    explanation: r`Cycle-specific drugs kill any dividing cell, so the normal tissues hit hardest are those with the most cells in cycle: marrow, gut epithelium and hair follicles. Cardiac muscle, skeletal muscle and neurons are not dividing and are largely spared. That is why low blood counts, mucositis and hair loss are the predictable side effects.`,
  },
  [r`Methotrexate blocks {{c1::dihydrofolate reductase}} and 5-fluorouracil blocks {{c2::thymidylate synthase}}, so both starve S phase of dTMP.`]: {
    question: r`Supplying reduced folate (leucovorin) protects normal cells from one of two S-phase drugs, methotrexate or 5-fluorouracil. Which drug is it, and what makes the rescue work?`,
    options: [r`Methotrexate; reduced folate bypasses thymidylate synthase`, r`5-Fluorouracil; reduced folate bypasses thymidylate synthase`, r`5-Fluorouracil; reduced folate bypasses dihydrofolate reductase`, r`Methotrexate; reduced folate bypasses dihydrofolate reductase`],
    correctAnswer: 3,
    explanation: r`Methotrexate blocks dihydrofolate reductase, the enzyme that regenerates reduced folate, so giving reduced folate directly gets around the block. 5-Fluorouracil blocks thymidylate synthase itself, and extra folate cofactor does not bypass that enzyme. The wrong choices swap which enzyme each drug inhibits.`,
  },
  [r`Fusing an S-phase cell with a G1 cell makes the G1 nucleus begin replicating. What did such fusion experiments establish?`]: {
    question: r`Cytoplasm taken from S-phase cells, with no nucleus, is injected into cells in early G₁. Based on what cell fusion experiments established, what is expected?`,
    options: [r`The G₁ nucleus keeps its schedule, set by an internal nuclear clock`, r`The G₁ nucleus begins replicating, driven by diffusible activators`, r`The G₁ nucleus condenses chromosomes, driven by diffusible MPF`, r`The G₁ nucleus stops its growth, held by diffusible inhibitors`],
    correctAnswer: 1,
    explanation: r`Fusion experiments showed that soluble factors in the cytoplasm, later identified as cyclin-CDK complexes, drive cycle transitions, so S-phase cytoplasm alone should start replication in a G₁ nucleus. An autonomous nuclear clock is the model those experiments ruled out. Premature condensation needs M-phase cytoplasm, not S-phase cytoplasm.`,
  },
  [r`How does decades-long meiotic arrest explain the maternal age effect in trisomy 21?`]: {
    question: r`Chromosome 21 nondisjunction rises sharply in the eggs of women over 35 but much less in the sperm of men the same age. What best explains the difference?`,
    options: [r`Oocyte cohesin is reloaded every month and is copied with errors`, r`Sperm cohesin was loaded before birth and is shielded by shugoshin`, r`Oocyte cohesin was loaded before birth and has decayed for decades`, r`Oocyte spindles were built before birth and have decayed for decades`],
    correctAnswer: 2,
    explanation: r`Oocytes enter meiosis in the fetus and stay arrested for decades, and the cohesin holding their chromosomes together is not replaced, so it weakens with age. Sperm are made continuously from puberty with freshly loaded cohesin. Cohesin is not reloaded monthly, and the spindle is assembled anew when meiosis resumes.`,
  },
  [r`What is the immediate result of failed cytokinesis after an otherwise normal mitosis, and how would you detect it?`]: {
    question: r`A human cell completes mitosis normally but cytokinesis fails. The cell is not stopped by p53 and goes through another S phase. What does it contain when it reaches G₂?`,
    options: [r`Two nuclei and 4N DNA in total`, r`One nucleus and 4N DNA in total`, r`Four nuclei and 8N DNA in total`, r`Two nuclei and 8N DNA in total`],
    correctAnswer: 3,
    explanation: r`Failed cytokinesis leaves two 2N nuclei in one cell, a binucleate tetraploid cell with 4N DNA. Replicating that DNA doubles it to 8N, still in two nuclei. Two nuclei with 4N is the state just after the failure, before S phase; one nucleus with 4N is an ordinary G₂ cell; and no step here makes four nuclei.`,
  },
  [r`High-risk HPV causes cancer because E6 drives degradation of {{c1::p53}} while E7 inactivates {{c2::Rb}}, releasing E2F.`]: {
    question: r`A cervical cell line expresses HPV E7 but the E6 gene has been deleted. The cells suffer DNA damage. What is their state?`,
    options: [r`E2F is bound, and p53 can still trigger arrest or apoptosis`, r`E2F is free, but p53 can still trigger arrest or apoptosis`, r`E2F is free, and p53 is degraded so no arrest can occur`, r`E2F is bound, but p53 is degraded so no arrest can occur`],
    correctAnswer: 1,
    explanation: r`E7 inactivates Rb, which releases E2F and drives S-phase genes. Degradation of p53 is the job of E6, so without E6 the p53 response to damage is intact. The wrong choices either leave E2F bound, which ignores E7, or give E7 the p53-destroying role that belongs to E6.`,
  },
}
